import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import DashboardTabs from '@/components/DashboardTabs.vue';
import axios from '@/utils/axios';
export default {
  name: 'TrashView',
  components: {
    DashboardTabs
  },
  data: () => ({
    files: [],
    cursor: null,
    loading: false,
    busy: false,
    search: '',
    error: ''
  }),
  computed: {
    visibleFiles() {
      const q = this.search.trim().toLowerCase();
      return this.files.filter(f => f.path.toLowerCase().includes(q) || f.name.toLowerCase().includes(q));
    }
  },
  mounted() {
    this.load(true);
  },
  methods: {
    async load(reset) {
      if (this.loading) return;
      this.loading = true;
      this.error = '';
      try {
        const {
          data
        } = await axios.get('/api/manage/trash', {
          params: reset ? {} : {
            cursor: this.cursor
          }
        });
        if (!data.success) throw new Error(data.error);
        this.files = reset ? data.files : [...new Map([...this.files, ...data.files].map(f => [f.id, f])).values()];
        this.cursor = data.cursor;
      } catch (e) {
        this.error = e.response?.data?.error || e.message || this.$t('trash.failed');
      } finally {
        this.loading = false;
      }
    },
    async act(row, action) {
      const purge = action === 'purge';
      try {
        await this.$confirm(this.$t(purge ? 'trash.purgeConfirm' : 'trash.restoreConfirm', {
          path: row.path
        }), this.$t(purge ? 'trash.purge' : 'trash.restore'), {
          type: purge ? 'warning' : 'info',
          confirmButtonText: this.$t(purge ? 'trash.purge' : 'trash.restore'),
          cancelButtonText: this.$t('dashboard.deleteConfirmCancel')
        });
      } catch {
        return;
      }
      this.busy = true;
      try {
        const endpoint = '/api/manage/trash/' + encodeURIComponent(row.id);
        const {
          data
        } = purge ? await axios.delete(endpoint) : await axios.post(endpoint + '/restore');
        if (!data.success) throw new Error(data.error);
        if (data.warning) this.$message.warning(data.warning);else this.$message.success(this.$t(purge ? 'trash.purged' : 'trash.restored'));
        this.files = this.files.filter(f => f.id !== row.id);
      } catch (e) {
        this.$message.error(e.response?.data?.error || e.message || this.$t('trash.failed'));
        await this.load(true);
      } finally {
        this.busy = false;
      }
    }
  }
};